// trees by ward: square columns on a grid, height = trees
values = [10, 38, 70, 67, 56, 43];
tallest = 40;  // mm
s = 15; per_row = 3; base = 2;
rows = ceil(len(values) / per_row);
cube([per_row * s, rows * s, base]);
for (i = [0 : len(values) - 1])
  translate([(i % per_row) * s, floor(i / per_row) * s, base]) cube([s - 1, s - 1, values[i] * tallest / max(values)]);

// riders by line: one layer per line, bottom first; diameter = riders
values = [17, 84, 37];
biggest = 80;  // mm
t = 2;  // layer thickness, mm
for (i = [0 : len(values) - 1])
  translate([0, 0, i * t]) cylinder(h = t, d = biggest * values[i] / max(values), $fn = 64);

// noise by hour: one spoke per hour, length = noise
values = [65, 76, 17, 50, 60];
longest = 60;  // mm
w = 6; h = 4;
cylinder(h = h, d = w * 2, $fn = 32);
for (i = [0 : len(values) - 1])
  rotate([0, 0, i * 360 / len(values)]) translate([0, -w / 2, 0]) cube([longest * values[i] / max(values), w, h]);

// trees by ward: one bar per ward, height = trees
values = [38, 12, 75, 6, 16, 56, 95];
